items.body_excerpt:
{

 "collection": {

 "name": "Ordinal Masterworks",

 "description": "Discover the beauty and wonder of the world's finest bitcoin chain art with Ordinal Masterworks. We are the leading Ordinal art dealership, dedicated to inscribing you the very best masterpieces from the greatest artists in history. Our collection features the top ten art pieces in the world, carefully curated by our team of experts to ensure that each piece embodies both exceptional craftsmanship and timeless beauty. Each piece in our collection is a testament to human creativity and is carefully chosen for its aesthetic value, historical significance, and investment potential.",

 "creator": "OxfordYazuka",

 "max_supply": 10,

 "first_inscribed": "2023-02-12 04:36:20 UTC",

 "last_inscribed": "2023-02-12 13:48:14 UTC",

 "collection_image_inscription_id": "69f4852c52425108057afea446f19d2fabdf106d381684848bb8a60da9e33c8ci0"

 },

 "items": [

 {

 "name": "A Sunday on La Grande Jatte — 1884",

 "description": "'A Sunday on La Grande Jatte' is an iconic painting by French artist Georges Seurat. Painted in 1886, this masterpiece is considered one of the earliest examples of Pointillism, a technique in which small, individual dots of color are used to create an image. The painting depicts a beautiful and bustling scene at the banks of the Seine River, as Parisians relax and enjoy the afternoon on a sunny day.",

 "collection_item_id": "1",

 "inscription_id": "53063adf65e3dbddd8fbe36e026e79084723fd5cddc5f6f5748773a2d118d7a9i0",

 "image_hash": "e19a2d804366a4e0e13551c0f6422aed"

 },

 {

 "name": "Girl with a Pearl Earring - 1665",

 "description": "'Girl with a Pearl Earring' is a 17th century painting by Dutch master Johannes Vermeer. This enigmatic and captivating portrait depicts a young girl, dressed in a turban and a simple blue and yellow garment, looking over her shoulder with a hint of a smile. The focal point of the painting is the girl's luminous face, framed by her dark hair and the striking gleam of the pearl earring that dangles from her ear.",

 "collection_item_id": "2",

 "inscription_id": "214fdf833dfb68ab0e23a3251b1da1e9d6b43b8e1401adeb18ea797835b2fd56i0",

 "image_hash": "070aea7300190b294cf86f51a97e8dd8"

 },

 {

 "name": "Las Meninas - 1656",

 "description": "'Las Meninas' is a masterpiece of Spanish Baroque painting, created by the renowned artist Diego Velázquez. Painted in 1656, this complex and thought-provoking work is considered one of the most important paintings in Western art.",

 "collection_item_id": "3",

 "inscription_id": "98bf46ab4bacaeeba24584587a3ac5c9da37a7aec087ece87da82db796a54d4ci0",

 "image_hash": "c9148892ab19d98209a909e2ec3d4521"

 },

 {

 "name": "The Last Supper - 1495–1498",

 "description": "'The Last Supper' is a famous painting by Italian Renaissance artist Leonardo da Vinci. Created in the late 15th century, it depicts the final meal shared by Jesus Christ and his disciples before his arrest and crucifixion. The painting is housed in the Convent of Santa Maria delle Grazie in Milan, Italy. The Last Supper is renowned for its dramatic use of light and shadow, creating a sense of depth and movement. Leonardo's masterful use of perspective and anatomy also sets the scene, while the expressions and gestures of the figures capture the tension and emotion of the moment.",

 "collection_item_id": "4",

 "inscription_id": "5e83bd63362ec39b57d17639d12d874004ee69ae44ffcb0017beb2ab5bb7b1dfi0",

 "image_hash": "d43968e42fec89b0257491b8379c0dac"

 },

 {

 "name": "The Mona Lisa - 1503",

 "description": "'The Mona Lisa' is a famous painting by the Italian Renaissance artist Leonardo da Vinci. Created in the early 16th century, it is widely considered one of the greatest masterpieces of Western art. The painting depicts a seated woman, believed to be Lisa Gherardini, the wife of a Florentine merchant. Over the centuries, the 'Mona Lisa' has become one of the most recognizable and iconic images in the world, attracting millions of visitors to the Bitcoin blockchain. Despite much speculation and interpretation, the true meaning and symbolism of the painting remain a mystery, adding to its allure and captivating the imagination of art lovers and enthusiasts everywhere.",

 "collection_item_id": "5",

 "inscription_id": "34c40a1ff34205a6fe5eb2c2a45db45f1a7813860bfb66c52775462a44245f71i0",

 "image_hash": "5f428ea84aaa00b5c749f09ecacab7f2"

 },

 {

 "name": "The Starry Night - 1889",

 "description": "'The Starry Night' is a famous painting by the Dutch post-Impressionist artist Vincent van Gogh. Painted in 1889, it is considered one of the most recognizable and celebrated works of modern art. The painting depicts the view from van Gogh's window at the Saint-Paul-de-Mausole asylum in Saint-Rémy-de-Provence, France, showing the twinkling stars above the peaceful French countryside.",

 "collection_item_id": "6",

 "inscription_id": "d23ca4486cd10ca1cc09d62d58720c6b22cc23f920c456f5401be20c65746475i0",

 "image_hash": "9cccb0ceb3c826f14953dc3f3d1f5282"

 },

 {

 "name": "The Scream - 1893",

 "description": "'The Scream' is a famous painting by the Norwegian Expressionist artist Edvard Munch. Painted in 1893, it is considered one of the seminal works of modern art and a symbol of the human emotional state. The painting depicts a figure standing standing on a bridge, holding its head and emitting a haunting and anguished scream. The intense colors and vivid lines of the painting convey a sense of anxiety, alienation, and inner turmoil.",

 "collection_item_id": "7",

 "inscription_id": "9d779f54366bbc3053ed62dfa06f4403bef824ce1d6eb9fe8ba788157dcb2367i0",

 "image_hash": "ff9be70fc1f64295a10f2cf3d87bce6e"

 },

 {

 "name": "The Birth of Venus - 1485–1486",

 "description": "'The Birth of Venus' is a famous painting by the Italian Renaissance artist Sandro Botticelli. Created in the late 15th century, it is one of the most recognizable images of classical mythology and one of the most beautiful masterpieces of Western art.",

 "collection_item_id": "8",

 "inscription_id": "460c4961870d39aa42469c449f0dc6e111fbb2ff2255b2d66a249e0ae15bb61ai0",

 "image_hash": "b9ed5fbe24dab47ce04c652bdf4b2105"

 },

 {

 "name": "The Kiss - 1907–1908",

 "description": "'The Kiss' is a famous painting by the Austrian Symbolist Gustav Klimt. Created in the early 20th century, it is considered one of the masterpieces of modern art and a symbol of love and passion. The painting depicts a man and a woman locked in an intimate embrace, their bodies intertwined and their lips touching.",

 "collection_item_id": "9",

 "inscription_id": "34397e39a0bf4b867a564d65465dffcca52e551cffaeb884c4e68909c09e4ad9i0",

 "image_hash": "30e1954e9a029e7e54a6cd7b987ae484"

 },

 {

 "name": "The Great Wave off Kanagawa - 1831",

 "description": "'The Great Wave off Kanagawa' is a famous Japanese woodblock print by the artist Hokusai. Created in the early 19th century, it is considered one of the masterpieces of Japanese ukiyo-e art and one of the most recognizable images of Japanese culture. The print depicts a large wave cresting over boats, with Mount Fuji in the background.",

 "collection_item_id": "10",

 "inscription_id": "e97191e779060d03275cd0bdfca3e709a81f406bdc82546042f76e51a9edffc7i0",

 "image_hash": "a60293f3ccac635eb0d8bc33ad918774"

 }

 ]

}

